-- Service data for ordering (D122 §9, D124; ticket #66; design
-- docs/deliverables/2026-10-21-service-data-design.md): bars, the tables' new columns and the
-- service tables. Generated by drizzle-kit, then edited by hand: row-level security, the
-- updated_at triggers and table_orders' fillfactor (its in-place updates stay HOT) are appended.
-- Privileges come from src/table-access.ts. `operators` is a system table: no tenant data, the
-- app only reads it. No data.
CREATE TABLE "restro"."alerts" (
