	"subject_id" text NOT NULL,
	"permission" text,
	"details" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"raised_at" timestamp with time zone DEFAULT now() NOT NULL,
	"next_repeat_at" timestamp with time zone,
	"done_at" timestamp with time zone,
	"done_by" text,
	"via" text,
	"telegram_message_ref" text,
	"source" text NOT NULL,
	"actor" text NOT NULL,
	"job_id" text NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "alerts_tenant_id_id_unique" UNIQUE("tenant_id","id"),
	CONSTRAINT "alerts_id_format" CHECK ("restro"."alerts"."id" ~ '^al_[0-9A-Za-z]+$'),
	CONSTRAINT "alerts_kind" CHECK ("restro"."alerts"."kind" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'),
	CONSTRAINT "alerts_audience" CHECK ("restro"."alerts"."audience" in ('venue', 'restro')),
	CONSTRAINT "alerts_subject_id" CHECK ("restro"."alerts"."subject_id" ~ '^[a-z]{2}_[0-9A-Za-z]+$'),
	CONSTRAINT "alerts_permission" CHECK ("restro"."alerts"."permission" is null or "restro"."alerts"."permission" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'),
	CONSTRAINT "alerts_details_object" CHECK (jsonb_typeof("restro"."alerts"."details") = 'object'),
	CONSTRAINT "alerts_done_by" CHECK ("restro"."alerts"."done_by" is null or "restro"."alerts"."done_by" ~ '^(system|guest|(user|staff|integration|operator):[A-Za-z0-9][A-Za-z0-9_.:-]{0,127})$'),
	CONSTRAINT "alerts_via" CHECK ("restro"."alerts"."via" is null or "restro"."alerts"."via" in ('guest_page', 'tonight', 'telegram', 'worker', 'provider')),
	CONSTRAINT "alerts_source" CHECK ("restro"."alerts"."source" in ('guest', 'staff', 'worker', 'provider', 'restro', 'pos')),
